export type Post = {
  id: string;
  title: string;
  body: string;
  createdAt: string;
};

const posts: Post[] = [];

export function getAllPosts(): Post[] {
  return [...posts];
}

export function addPost(title: string, body: string): Post {
  const post: Post = {
    id: crypto.randomUUID(),
    title,
    body,
    createdAt: new Date().toISOString(),
  };
  posts.push(post);
  return post;
}

